#include "sdes.h"
int main(void){int key;if(!sd_parse_bits("0111111101",10,&key))return 1;int iv=0xaa,p[2]={0x01,0x23},c[2],back[2];c[0]=sd_encrypt(p[0]^iv,key);c[1]=sd_encrypt(p[1]^c[0],key);back[0]=sd_decrypt(c[0],key)^iv;back[1]=sd_decrypt(c[1],key)^c[0];printf("S-DES CBC; key=01111 11101, IV=1010 1010\nPlaintext blocks: ");for(int i=0;i<2;i++){for(int b=7;b>=0;b--)putchar((p[i]>>b)&1?'1':'0');putchar(' ');}printf("\nCiphertext blocks: ");for(int i=0;i<2;i++){for(int b=7;b>=0;b--)putchar((c[i]>>b)&1?'1':'0');putchar(' ');}printf("\nRecovered plaintext: ");for(int i=0;i<2;i++){for(int b=7;b>=0;b--)putchar((back[i]>>b)&1?'1':'0');putchar(' ');}puts("\nThe program demonstrates CBC mechanics for the PDF's S-DES test key and IV.");return 0;}
